from pathlib import Path
p=Path('outputs/README.md'); s=p.read_text(encoding='utf-8-sig')
s=s.replace('The table can show whether higher preparation answers tend to appear alongside higher confidence answers. It cannot show cause and effect. If only a few students answer, show the number of responses beside every result and avoid broad claims.','The table shows average confidence at each preparation rating, and the script calculates Spearman rank correlation to summarize whether the two ratings tend to rise together. These are associations between self-reported answers; they cannot show that preparation causes an actual placement. The form does not ask whether respondents received placement offers. If only a few students answer, show the number of responses beside each result and avoid broad claims.')
s=s.replace('“We used frequency counts and averages to summarize the survey. We then cross-tabulated placement-preparation ratings against placement-confidence ratings to explore whether the answers were associated. The survey is anonymous and self-reported, so the results describe our respondents and do not prove causation or represent official placement data.”','“We used frequency counts and averages to summarize the survey. We compared average confidence across preparation ratings and calculated Spearman rank correlation to see whether the ratings tended to move together. This tests association in our respondents’ self-reports; it cannot show that preparation caused actual placement, because we did not measure placement offers or run an experiment.”')
p.write_text(s,encoding='utf-8')
